"""SQL Injection Lab — Secure | CWE-89 | OWASP A03:2021
Demonstrates: parameterized queries prevent SQL injection.
"""
from __future__ import annotations
import os, re, sqlite3
from typing import Any
from flask import Flask, jsonify, request

app = Flask(__name__)
app.secret_key = "lab-sqli-secure-key"

_conn = sqlite3.connect(":memory:", check_same_thread=False)
_conn.row_factory = sqlite3.Row
_conn.executescript(
    "CREATE TABLE users "
    "(id INTEGER PRIMARY KEY, username TEXT, password TEXT, role TEXT);"
)
_conn.executemany(
    "INSERT INTO users VALUES (?,?,?,?)",
    [(1,"alice","lab_alice_pass","user"),
     (2,"bob","lab_bob_pass","user"),
     (3,"admin","lab_admin_pass","admin")]
)
_conn.commit()

PAGE = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>SQL Injection Sécurisé</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,sans-serif;background:#0d1117;color:#e6edf3}.bn{padding:12px 24px;display:flex;align-items:center;gap:10px;font-weight:600;font-size:.93em}.bn.v{background:#da3633}.bn.s{background:#238636}.ctr{max-width:1100px;margin:0 auto;padding:20px}h1{font-size:1.35em;margin-bottom:4px}h2{font-size:.97em;margin:14px 0 6px;color:#58a6ff;border-left:3px solid #58a6ff;padding-left:8px}.mt{color:#8b949e;font-size:.84em;margin-bottom:16px}.bge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:.74em;font-weight:600;margin-right:4px}.bcwe{background:#1a1f2e;border:1px solid #30363d;color:#8b949e}.bo{background:#0d2145;border:1px solid #1f6feb;color:#58a6ff}.br{background:#4a0d0d;border:1px solid #da3633;color:#f85149}.bgrn{background:#0d4a1e;border:1px solid #238636;color:#3fb950}.tabs{display:flex;border-bottom:2px solid #21262d;margin-bottom:18px}.tb{padding:9px 18px;background:none;border:none;color:#8b949e;cursor:pointer;font-size:.87em;border-bottom:2px solid transparent;margin-bottom:-2px}.tb.a{color:#58a6ff;border-bottom-color:#58a6ff;font-weight:600}.tp{display:none}.tp.a{display:block}.cd{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:16px;margin-bottom:12px}.fg{margin-bottom:10px}.fg label{display:block;font-size:.81em;color:#8b949e;margin-bottom:3px}.fg input{width:100%;padding:8px 10px;background:#0d1117;border:1px solid #30363d;border-radius:5px;color:#e6edf3;font-size:.87em;font-family:monospace}.btn{padding:8px 16px;border-radius:5px;cursor:pointer;font-size:.87em;font-weight:600;border:none;margin-right:6px}.btn:hover{opacity:.85}.btr{background:#da3633;color:#fff}.btg{background:#238636;color:#fff}.btgr{background:#21262d;border:1px solid #30363d;color:#e6edf3}.co{background:#0d1117;border:1px solid #30363d;border-left:3px solid #da3633;border-radius:5px;padding:12px;font-family:monospace;font-size:.79em;line-height:1.6;margin:6px 0;white-space:pre-wrap}.co.g{border-left-color:#3fb950}.bx{border-radius:6px;padding:10px 13px;font-size:.84em;margin:7px 0;line-height:1.5}.bx.d{background:#4a0d0d;border:1px solid #da3633;color:#f85149}.bx.w{background:#3d1f00;border:1px solid #d29922;color:#d29922}.bx.i{background:#0d2145;border:1px solid #1f6feb;color:#58a6ff}.bx.s{background:#0d4a1e;border:1px solid #238636;color:#3fb950}.g2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.gd{display:grid;grid-template-columns:255px 1fr;gap:14px}@media(max-width:660px){.g2,.gd{grid-template-columns:1fr}}.pl{background:#0d1117;border:1px solid #30363d;border-radius:5px;padding:9px;margin-bottom:7px}.pl .lb{font-size:.74em;color:#58a6ff;font-weight:700;margin-bottom:2px}.pl .pc{font-family:monospace;font-size:.77em;margin-bottom:3px;word-break:break-all}.pl .pd{font-size:.76em;color:#8b949e;margin-bottom:4px}.res{background:#0d1117;border:1px solid #30363d;border-radius:5px;padding:12px;margin-top:10px;min-height:48px}table{width:100%;border-collapse:collapse;font-size:.81em}th,td{padding:7px 9px;border:1px solid #21262d}th{background:#161b22;color:#8b949e}code{background:#0d1117;padding:1px 4px;border-radius:2px;font-size:.84em;font-family:monospace}p{margin-bottom:5px;line-height:1.55;font-size:.87em;color:#8b949e}ul{padding-left:17px;color:#8b949e;font-size:.87em;line-height:1.85}</style></head><body><div class="bn s"><i class="fa-solid fa-circle-check"></i> SQL INJECTION SÉCURISÉ — SECURISE <span>| Requêtes paramétrées SQLite | CWE-89 | Vulnérable: localhost:5021</span></div><div class="ctr"><h1>SQL Injection — Authentification sécurisée</h1><div class="mt"><span class="bge bgrn">Sécurisé</span><span class="bge bcwe">CWE-89</span><span class="bge bo">OWASP A03:2021</span></div><div class="tabs"><button class="tb a" onclick="st(\'demo\',this)"><i class="fa-solid fa-flask"></i> Démonstration</button><button class="tb" onclick="st(\'theory\',this)"><i class="fa-solid fa-book"></i> Théorie</button><button class="tb" onclick="st(\'code\',this)"><i class="fa-solid fa-code"></i> Code</button><button class="tb" onclick="st(\'fix\',this)"><i class="fa-solid fa-shield-halved"></i> Correction</button></div><div id="t-demo" class="tp a"><div class="gd"><div><div class="cd"><h2><i class="fa-solid fa-crosshairs"></i> Testez les mêmes payloads</h2><div class="bx s"><i class="fa-solid fa-circle-check"></i> Les requêtes paramétrées traitent l\'entrée comme <strong>donnée pure</strong>, jamais comme code SQL.</div><div class="pl"><div class="lb">1 — Login correct</div><div class="pc">alice / lab_alice_pass</div><div class="pd">Doit fonctionner normalement.</div><button class="btn btgr" onclick="f(\'alice\',\'lab_alice_pass\')"><i class="fa-solid fa-play"></i> Normal</button></div><div class="pl"><div class="lb">2 — Tautologie (bloqué)</div><div class="pc">admin / \' OR \'1\'=\'1</div><div class="pd">Comparé littéralement → aucun utilisateur trouvé.</div><button class="btn btgr" onclick="f(\'admin\',&quot;\' OR \'1\'=\'1&quot;)"><i class="fa-solid fa-play"></i> Tester</button></div><div class="pl"><div class="lb">3 — Commentaire (bloqué)</div><div class="pc">admin\'-- / x</div><div class="pd">L\'apostrophe est échappée → comparée littéralement.</div><button class="btn btgr" onclick="f(&quot;admin\'--&quot;,\'x\')"><i class="fa-solid fa-play"></i> Tester</button></div><div class="pl"><div class="lb">4 — UNION (bloqué)</div><div class="pc">\' UNION SELECT... / x</div><div class="pd">Traité comme valeur → aucun résultat.</div><button class="btn btgr" onclick="f(&quot;\' UNION SELECT 1,\'a\',\'b\',\'admin\'--&quot;,\'x\')"><i class="fa-solid fa-play"></i> Tester</button></div></div></div><div><div class="cd"><h2><i class="fa-solid fa-circle-check"></i> Authentification sécurisée</h2><div class="bx s"><i class="fa-solid fa-shield-halved"></i> <strong>Défenses :</strong> Requêtes paramétrées SQLite | Les ? séparent code et données | Validation d\'entrée</div><div class="fg"><label>Nom d\'utilisateur</label><input id="fu" value="alice"></div><div class="fg"><label>Mot de passe</label><input id="fp" value="lab_alice_pass"></div><div style="font-size:.79em;color:#6e7681;margin-bottom:8px">Requête: <code>SELECT * FROM users WHERE username = ? AND password = ?</code></div><div style="font-size:.79em;color:#6e7681;margin-bottom:8px">Paramètres: <code id="params">(\'alice\', \'lab_alice_pass\')</code></div><button class="btn btg" onclick="doLogin()"><i class="fa-solid fa-right-to-bracket"></i> Se connecter</button></div><div class="res" id="lr"><p style="color:#6e7681;font-size:.82em">Résultat ici...</p></div><div class="bx i" style="margin-top:8px"><i class="fa-solid fa-magnifying-glass"></i> Comparez avec <a href="http://localhost:5021" style="color:#58a6ff">localhost:5021</a>. Même payload, résultat différent : accès refusé.</div></div></div></div><div id="t-theory" class="tp"><div class="g2"><div><div class="cd"><h2><i class="fa-solid fa-shield-halved"></i> Requêtes paramétrées</h2><p>La défense fondamentale contre SQLi est de séparer le code SQL des données utilisateur.</p><div class="co g">Requête paramétrée :\n  query = "SELECT * FROM users WHERE username = ? AND password = ?"\n  cursor.execute(query, (username, password))\n\nSQLite remplace les ? avec les valeurs en les échappant :\n  username = "admin\'--"\n  → SQLite compare littéralement la chaîne "admin\'--"\n  → Aucun utilisateur ne correspond → accès refusé\n\nL\'apostrophe n\'est JAMAIS interprétée comme du SQL.</div></div></div><div><div class="cd"><h2><i class="fa-solid fa-list-check"></i> Toutes les défenses</h2><ul><li><strong>Requêtes paramétrées</strong> — séparation code/données</li><li><strong>ORM</strong> — SQLAlchemy, Django ORM (même principe)</li><li><strong>Validation d\'entrée</strong> — allowlist de caractères</li><li><strong>Moindre privilège</strong> — compte BDD avec droits minimaux</li><li><strong>Messages d\'erreur génériques</strong> — ne pas révéler la structure SQL</li></ul><h2><i class="fa-solid fa-book-open"></i> Références</h2><div class="bx i">CWE-89 — SQL Injection<br>OWASP A03:2021 — Injection<br>OWASP SQL Injection Prevention Cheat Sheet</div></div></div></div></div><div id="t-code" class="tp"><div class="g2"><div><div class="cd"><h2 style="color:#3fb950"><i class="fa-solid fa-circle-check"></i> Code sécurisé (ici)</h2><div class="co g">username = request.json["username"]\npassword = request.json["password"]\n\n# SECURE — requête paramétrée\nquery = (\n    "SELECT * FROM users "\n    "WHERE username = ? AND password = ?"\n)\ncursor.execute(query, (username, password))\n# Les ? sont des placeholders SQLite\n# username = "admin\'--"\n# → SQLite échappe: comparé comme texte\n# → aucun utilisateur trouvé → 401</div></div></div><div><div class="cd"><h2 style="color:#f85149"><i class="fa-solid fa-triangle-exclamation"></i> Code vulnérable (:5021)</h2><div class="co">query = (\n    "SELECT * FROM users "\n    "WHERE username=\'" + username + "\' "\n    "AND password=\'" + password + "\'"\n)\ncursor.execute(query)  # injection possible</div></div></div></div></div><div id="t-fix" class="tp"><div class="g2"><div><div class="cd"><h2><i class="fa-solid fa-arrows-left-right"></i> Comparaison</h2><table><tr><th>Entrée</th><th style="color:#f85149">:5021</th><th style="color:#3fb950">Ici</th></tr><tr><td>alice / correct</td><td>OK</td><td>OK</td></tr><tr><td>admin / \' OR \'1\'=\'1</td><td style="color:#f85149">Bypass !</td><td style="color:#3fb950">Rejeté</td></tr><tr><td>admin\'-- / x</td><td style="color:#f85149">Bypass !</td><td style="color:#3fb950">Rejeté</td></tr><tr><td>\' UNION SELECT...</td><td style="color:#f85149">Données injectées</td><td style="color:#3fb950">Rejeté</td></tr></table></div></div><div><div class="cd"><h2><i class="fa-solid fa-circle-check"></i> Résumé</h2><div class="bx s">La requête paramétrée (<code>?</code>) est la défense principale.<br>Les données utilisateur ne sont JAMAIS interprétées comme du code SQL.<br>Une apostrophe dans le mot de passe devient un caractère ordinaire.</div></div></div></div></div></div><script>function st(n,b){document.querySelectorAll(\'.tp\').forEach(p=>p.classList.remove(\'a\'));document.querySelectorAll(\'.tb\').forEach(x=>x.classList.remove(\'a\'));document.getElementById(\'t-\'+n).classList.add(\'a\');if(b)b.classList.add(\'a\');}function f(u,p){document.getElementById(\'fu\').value=u;document.getElementById(\'fp\').value=p;updateP();}function updateP(){  const u=document.getElementById(\'fu\').value,p=document.getElementById(\'fp\').value;  document.getElementById(\'params\').textContent="(\'"+u+"\', \'"+p+"\')";}document.getElementById(\'fu\').addEventListener(\'input\',updateP);document.getElementById(\'fp\').addEventListener(\'input\',updateP);function doLogin(){  const u=document.getElementById(\'fu\').value,p=document.getElementById(\'fp\').value;  fetch(\'/api/login\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({username:u,password:p})})    .then(r=>r.json().then(d=>({s:r.status,d}))).then(({s,d})=>{      const el=document.getElementById(\'lr\');      if(s===200){        el.innerHTML=\'<div class="bx s"><i class="fa-solid fa-circle-check"></i> Authentifié: \'+d.username+\' (\'+d.role+\')</div>\';      }else{        el.innerHTML=\'<div class="bx s"><i class="fa-solid fa-lock"></i> Accès refusé — paramètre traité comme texte, pas du code SQL.</div>\';      }      el.innerHTML+=\'<div style="font-size:.77em;color:#6e7681;margin-top:6px">Requête: <code>SELECT * FROM users WHERE username = ? AND password = ?</code></div>\';    });}</script></body></html>'

@app.route("/")
def index() -> Any:
    return PAGE

@app.route("/api/login", methods=["POST"])
def api_login() -> Any:
    data = request.get_json(force=True, silent=True) or {}
    username = str(data.get("username", ""))
    password = str(data.get("password", ""))

    # SECURE: parameterized query — user input never becomes SQL code
    query = "SELECT * FROM users WHERE username = ? AND password = ?"
    cursor = _conn.execute(query, (username, password))
    row = cursor.fetchone()

    if row:
        return jsonify({"status": "authenticated", "username": row["username"], "role": row["role"]})
    return jsonify({"status": "failed", "message": "Identifiants invalides"}), 401

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)), debug=False)
